<?php $this->start('scripts') ?><script>const settingsButtons=[...document.querySelectorAll('[data-settings-tab]')],settingsPanels=[...document.querySelectorAll('[data-settings-panel]')],settingsMainForm=document.querySelector('.studio-settings-form');const showSettingsTab=tab=>{settingsButtons.forEach(button=>button.classList.toggle('active',button.dataset.settingsTab===tab));settingsPanels.forEach(panel=>panel.classList.toggle('active',panel.dataset.settingsPanel===tab));settingsMainForm?.classList.toggle('modules-active',tab==='modules');history.replaceState(null,'','#'+tab)};settingsButtons.forEach(button=>button.addEventListener('click',()=>showSettingsTab(button.dataset.settingsTab)));const initialSettingsTab=location.hash.slice(1);if(settingsButtons.some(button=>button.dataset.settingsTab===initialSettingsTab))showSettingsTab(initialSettingsTab);const mailProvider=document.getElementById('settings-mail-provider');mailProvider?.addEventListener('change',()=>{const hosts=JSON.parse(mailProvider.dataset.sesHosts||'{}');if(!hosts[mailProvider.value])return;document.getElementById('settings-mail-host').value=hosts[mailProvider.value];document.getElementById('settings-mail-port').value='587';document.getElementById('settings-mail-secure').value='tls'});</script><?php $this->stop() ?>
